package data_structures.trees;
import java.util.*;
import java.util.function.*;
import java.math.*;

public class BTree {
public static class Tree<T> implements Iterable<T>{private static class Node<T>{List<T> keys=new ArrayList<>();List<Node<T>> children=new ArrayList<>();boolean leaf(){return children.isEmpty();}}public final int minDegree;private final Comparator<T> compare;private Node<T> root=new Node<>();private int count;public Tree(){this(2,shared.Compare::defaultCompare);}public Tree(int degree){this(degree,shared.Compare::defaultCompare);}public Tree(int degree,Comparator<T> c){if(degree<2)throw new IllegalArgumentException();minDegree=degree;compare=c;}public int size(){return count;}public int height(){int h=1;for(Node<T> n=root;!n.leaf();n=n.children.get(0))h++;return h;}private int lower(Node<T> n,T v){int l=0,h=n.keys.size();while(l<h){int m=(l+h)/2;if(compare.compare(n.keys.get(m),v)<0)l=m+1;else h=m;}return l;}public boolean has(T v){Node<T> n=root;while(true){int i=lower(n,v);if(i<n.keys.size()&&compare.compare(n.keys.get(i),v)==0)return true;if(n.leaf())return false;n=n.children.get(i);}}public boolean insert(T v){if(has(v))return false;if(root.keys.size()==2*minDegree-1){Node<T> n=new Node<>();n.children.add(root);split(n,0);root=n;}insertNonFull(root,v);count++;return true;}private void split(Node<T> p,int i){Node<T> f=p.children.get(i),r=new Node<>();r.keys.addAll(f.keys.subList(minDegree,f.keys.size()));f.keys.subList(minDegree,f.keys.size()).clear();T median=f.keys.remove(f.keys.size()-1);if(!f.leaf()){r.children.addAll(f.children.subList(minDegree,f.children.size()));f.children.subList(minDegree,f.children.size()).clear();}p.keys.add(i,median);p.children.add(i+1,r);}private void insertNonFull(Node<T> n,T v){int i=lower(n,v);if(n.leaf()){n.keys.add(i,v);return;}if(n.children.get(i).keys.size()==2*minDegree-1){split(n,i);if(compare.compare(v,n.keys.get(i))>0)i++;}insertNonFull(n.children.get(i),v);}public boolean delete(T v){if(!has(v))return false;remove(root,v);if(root.keys.isEmpty()&&!root.leaf())root=root.children.get(0);count--;return true;}private T min(Node<T> n){while(!n.leaf())n=n.children.get(0);return n.keys.get(0);}private T max(Node<T> n){while(!n.leaf())n=n.children.get(n.children.size()-1);return n.keys.get(n.keys.size()-1);}private void merge(Node<T> n,int i){Node<T> l=n.children.get(i),r=n.children.remove(i+1);l.keys.add(n.keys.remove(i));l.keys.addAll(r.keys);l.children.addAll(r.children);}private void remove(Node<T> n,T v){int i=lower(n,v),t=minDegree;if(i<n.keys.size()&&compare.compare(n.keys.get(i),v)==0){if(n.leaf()){n.keys.remove(i);return;}Node<T> l=n.children.get(i),r=n.children.get(i+1);if(l.keys.size()>=t){T p=max(l);n.keys.set(i,p);remove(l,p);}else if(r.keys.size()>=t){T s=min(r);n.keys.set(i,s);remove(r,s);}else{merge(n,i);remove(l,v);}return;}if(n.leaf())return;Node<T> child=n.children.get(i);if(child.keys.size()<t){Node<T> l=i>0?n.children.get(i-1):null,r=i+1<n.children.size()?n.children.get(i+1):null;if(l!=null&&l.keys.size()>=t){child.keys.add(0,n.keys.get(i-1));n.keys.set(i-1,l.keys.remove(l.keys.size()-1));if(!l.leaf())child.children.add(0,l.children.remove(l.children.size()-1));}else if(r!=null&&r.keys.size()>=t){child.keys.add(n.keys.get(i));n.keys.set(i,r.keys.remove(0));if(!r.leaf())child.children.add(r.children.remove(0));}else if(r!=null)merge(n,i);else{merge(n,i-1);child=n.children.get(i-1);}}remove(child,v);}public List<T> toArray(){List<T> o=new ArrayList<>();walk(root,o);return o;}private void walk(Node<T> n,List<T> o){for(int i=0;i<n.keys.size();i++){if(!n.leaf())walk(n.children.get(i),o);o.add(n.keys.get(i));}if(!n.leaf())walk(n.children.get(n.keys.size()),o);}public Iterator<T> iterator(){return toArray().iterator();}}
}
